package com.andye.warmod.radar.station;import com.andye.warmod.WarMod;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.radar.RadarTrackingService;import com.andye.warmod.radar.station.network.RadarStationNetworking;import java.util.*;import net.minecraft.SharedConstants;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.phys.Vec3;public final class RadarStationTrackingService {private RadarStationTrackingService(){}public static void tick(ServerLevel level){long now=level.getGameTime();if((now&1L)!=0)return;List<RadarTrackingService.RadarTrackTelemetry> telemetry=RadarTrackingService.currentTelemetry(level,now);Set<UUID>active=new HashSet<>();for(var t:telemetry)active.add(t.trackId());for(var record:RadarStationSavedData.get(level).records()){if(!(level.getBlockEntity(record.centre())instanceof RadarStationBlockEntity station)||!station.radarId().equals(record.radarId()))continue;double previous=RadarSweepMath.angleDegrees(now-2,station.phaseOffset()),current=RadarSweepMath.angleDegrees(now,station.phaseOffset());List<RadarStationObservation>fresh=new ArrayList<>();boolean changed=false;Vec3 centre=Vec3.atCenterOf(record.centre());for(var t:telemetry){if(t.kind()==com.andye.warmod.radar.RadarTrackKind.INTERCEPTOR)continue;double dx=t.currentPosition().x-centre.x,dz=t.currentPosition().z-centre.z;if(dx*dx+dz*dz>RadarStationConstants.DETECTION_RANGE_BLOCKS*RadarStationConstants.DETECTION_RANGE_BLOCKS)continue;double bearing=RadarSweepMath.bearingFrom(centre,t.currentPosition());if(!RadarSweepMath.crossed(previous,current,bearing,RadarStationConstants.BEAM_WIDTH_DEGREES))continue;Vec3 impact=t.predictedImpactPosition();double ix=impact.x-centre.x,iz=impact.z-centre.z;boolean threat=ix*ix+iz*iz<=station.warningRadius()*station.warningRadius();var observation=new RadarStationObservation(t.trackId(),t.snapshot(),t.currentPosition(),t.currentVelocity(),impact,now,now,threat);changed|=station.observe(level,observation);fresh.add(observation);if(SharedConstants.IS_RUNNING_IN_IDE)WarMod.LOGGER.info("Radar station {} sweep detected {}: bearing={}, sweep={}",station.radarId(),t.trackId(),bearing,current);}changed|=station.prune(level,now,active);if(!fresh.isEmpty())RadarStationNetworking.sendObservations(station,fresh);if(changed)RadarStationNetworking.sendState(station);}}}